from lib import *
from fractions import Fraction as F
from math import gcd
LESSON = 'ប្រភាគ'

def fr(a, b=None):
    """a/b or Fraction -> \\dfrac{p}{q} (negative sign in front); integers stay integers."""
    f = F(a) if b is None else F(a, b)
    return frac(f)
def mx(f): return f'\\dfrac{{{f.numerator}}}{{{f.denominator}}}' if f.denominator != 1 else str(f.numerator)
def raw(a, b): return f'\\dfrac{{{a}}}{{{b}}}'          # keeps the fraction exactly as written (not simplified)
def W(ans, cand, k=3):
    out = []
    for c in list(cand):
        c = F(c)
        if c != ans and c not in out: out.append(c)
    d = 1
    while len(out) < k:
        c = ans + F(d, 7)
        if c != ans and c not in out: out.append(c)
        d += 1
    return [M(fr(c)) for c in out[:k]]

